import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import './ProjetoList.css';

const ProjetoList = () => {
  const [projetos, setProjetos] = useState([]);
  const [loading, setLoading] = useState(true);
  const { clienteId } = useParams();
  const [newAtividade, setNewAtividade] = useState({ nome: '', descricao: '' });
  const [selectedProjetoId, setSelectedProjetoId] = useState(null);

  useEffect(() => {
    const fetchProjetos = async () => {
      try {
        const response = await axios.get(`http://localhost:8080/clientes/${clienteId}/projetos`);
        setProjetos(response.data);
      } catch (err) {
        console.error("Erro ao carregar projetos", err);
      } finally {
        setLoading(false);
      }
    };

    fetchProjetos();
  }, [clienteId]);

  const handleCreateAtividade = async (projetoId) => {
    try {
      const response = await axios.post(
        `http://localhost:8080/clientes/${clienteId}/projetos/${projetoId}/atividades`,
        newAtividade
      );
      alert('Atividade criada com sucesso!');
      setSelectedProjetoId(null); // Fechar o formulário
      setNewAtividade({ nome: '', descricao: '' }); // Limpar o formulário
    } catch (error) {
      console.error('Erro ao criar atividade', error);
      alert('Erro ao criar atividade');
    }
  };

  return (
    <div className="projeto-list">
      <h3>Projetos do Cliente</h3>
      {loading ? (
        <p>Carregando...</p>
      ) : (
        <div className="projetos-container">
          {projetos.length === 0 ? (
            <p>Não há projetos para este cliente.</p>
          ) : (
            projetos.map((projeto) => (
              <div className="projeto-card" key={projeto.id}>
                <h4>{projeto.nome}</h4>
                <p>{projeto.descricao}</p>

                {/* Link para atividades */}
                <Link to={`/clientes/${clienteId}/projetos/${projeto.id}/atividades`} className="detalhes-link">
                  Ver Atividades
                </Link>

                {/* Botão para abrir o formulário de criar atividade */}
                <button onClick={() => setSelectedProjetoId(projeto.id)}>Adicionar Atividade</button>

                {/* Formulário para adicionar atividade */}
                {selectedProjetoId === projeto.id && (
                  <div className="atividade-form">
                    <input
                      type="text"
                      placeholder="Nome da Atividade"
                      value={newAtividade.nome}
                      onChange={(e) => setNewAtividade({ ...newAtividade, nome: e.target.value })}
                    />
                    <textarea
                      placeholder="Descrição da Atividade"
                      value={newAtividade.descricao}
                      onChange={(e) => setNewAtividade({ ...newAtividade, descricao: e.target.value })}
                    />
                    <button onClick={() => handleCreateAtividade(projeto.id)}>Salvar Atividade</button>
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

export default ProjetoList;
